44	// UnupgradedControlPlaneInstances returns a list of control plane instances that have not yet been upgraded.
45	//
46	// NB. This function can only be called after the current control plane instance has been upgraded already.
47	// Because it determines whether the other control plane instances have been upgraded by checking whether
48	// the kube-apiserver image of other control plane instance is the same as that of this instance.
49	func UnupgradedControlPlaneInstances(client clientset.Interface, nodeName string) ([]string, error) {
50		selector := labels.SelectorFromSet(labels.Set(map[string]string{
51			"component": kubeadmconstants.KubeAPIServer,
52		}))
53		pods, err := client.CoreV1().Pods(metav1.NamespaceSystem).List(context.TODO(), metav1.ListOptions{
54			LabelSelector: selector.String(),
55		})
56		if err != nil {
57			return nil, errors.Wrap(err, "failed to list kube-apiserver Pod from cluster")
58		}
59		if len(pods.Items) == 0 {
60			return nil, errors.Errorf("cannot find kube-apiserver Pod by label selector: %v", selector.String())
61		}
62	
63		nodeImageMap := map[string]string{}
64	
65		for _, pod := range pods.Items {
66			found := false
67			for _, c := range pod.Spec.Containers {
68				if c.Name == kubeadmconstants.KubeAPIServer {
69					nodeImageMap[pod.Spec.NodeName] = c.Image
70					found = true
71					break
72				}
73			}
74			if !found {
75				return nil, errors.Errorf("cannot find container by name %q for Pod %v", kubeadmconstants.KubeAPIServer, klog.KObj(&pod))
76			}
77		}
78	
79		upgradedImage, ok := nodeImageMap[nodeName]
80		if !ok {
81			return nil, errors.Errorf("cannot find kube-apiserver image for current control plane instance %v", nodeName)
82		}
83	
84		unupgradedNodes := sets.New[string]()
85		for node, image := range nodeImageMap {
86			if image != upgradedImage {
87				unupgradedNodes.Insert(node)
88			}
89		}
90	
91		if len(unupgradedNodes) > 0 {
92			return sets.List(unupgradedNodes), nil
93		}
94	
95		return nil, nil
96	}
