98	// WriteKubeletConfigFiles writes the kubelet config file to disk, but first creates a backup of any existing one.
99	func WriteKubeletConfigFiles(cfg *kubeadmapi.InitConfiguration, kubeletDir string, kubeConfigDir string, patchesDir string, dryRun bool, out io.Writer) error {
100		// Create a copy of the kubelet config file in the /etc/kubernetes/tmp or kubeConfigDir.
101		backupDir, err := kubeadmconstants.CreateTimestampDir(kubeConfigDir, "kubeadm-kubelet-config")
102		if err != nil {
103			return err
104		}
105		klog.Warningf("Using temporary directory %s for kubelet config. To override it set the environment variable %s",
106			backupDir, kubeadmconstants.EnvVarUpgradeDryRunDir)
107	
108		src := filepath.Join(kubeletDir, kubeadmconstants.KubeletConfigurationFileName)
109		dest := filepath.Join(backupDir, kubeadmconstants.KubeletConfigurationFileName)
110	
111		if !dryRun {
112			_, _ = fmt.Fprintf(out, "[upgrade] Backing up kubelet config file to %s\n", dest)
113			err := kubeadmutil.CopyFile(src, dest)
114			if err != nil {
115				return errors.Wrap(err, "error backing up the kubelet config file")
116			}
117		} else {
118			_, _ = fmt.Fprintf(out, "[dryrun] Would back up kubelet config file to %s\n", dest)
119		}
120	
121		if features.Enabled(cfg.FeatureGates, features.NodeLocalCRISocket) {
122			// If instance-config.yaml exist on disk, we don't need to create it.
123			_, err := os.Stat(filepath.Join(kubeletDir, kubeadmconstants.KubeletInstanceConfigurationFileName))
124			// After the NodeLocalCRISocket feature gate is removed, os.IsNotExist(err) should also be removed.
125			// If there is no instance configuration, it indicates that the configuration on the node has been corrupted,
126			// and an error needs to be reported.
127			if os.IsNotExist(err) {
128				var containerRuntimeEndpoint string
129				var kubeletFlags []kubeadmapi.Arg
130				dynamicFlags, err := kubeletphase.ReadKubeletDynamicEnvFile(filepath.Join(kubeletDir, kubeadmconstants.KubeletEnvFileName))
131				if err == nil {
132					args := kubeadmutil.ArgumentsFromCommand(dynamicFlags)
133					for _, arg := range args {
134						if arg.Name == "container-runtime-endpoint" {
135							containerRuntimeEndpoint = arg.Value
136							continue
137						}
138						kubeletFlags = append(kubeletFlags, arg)
139					}
140					if len(containerRuntimeEndpoint) != 0 {
141						if err := kubeletphase.WriteKubeletArgsToFile(kubeletFlags, nil, kubeletDir); err != nil {
142							return err
143						}
144					}
145				} else if dryRun {
146					_, _ = fmt.Fprintf(out, "[dryrun] would read the flag --container-runtime-endpoint value from %q, which is missing. "+
147						"Using default socket %q instead", kubeadmconstants.KubeletEnvFileName, kubeadmconstants.DefaultCRISocket)
148					containerRuntimeEndpoint = kubeadmconstants.DefaultCRISocket
149				} else {
150					return errors.Wrap(err, "error reading kubeadm flags file")
151				}
152	
153				kubeletConfig := &kubeletconfig.KubeletConfiguration{
154					ContainerRuntimeEndpoint: containerRuntimeEndpoint,
155				}
156	
157				if err := kubeletphase.WriteInstanceConfigToDisk(kubeletConfig, kubeletDir); err != nil {
158					return errors.Wrap(err, "error writing kubelet instance configuration")
159				}
160	
161				if dryRun { // Print what contents would be written
162					err = dryrunutil.PrintDryRunFile(kubeadmconstants.KubeletInstanceConfigurationFileName, kubeletDir, kubeadmconstants.KubeletRunDirectory, out)
163					if err != nil {
164						return errors.Wrap(err, "error printing kubelet instance configuration file on dryrun")
165					}
166				}
167			}
168		}
169	
170		// Write the configuration for the kubelet down to disk so the upgraded kubelet can start with fresh config
171		if err := kubeletphase.WriteConfigToDisk(&cfg.ClusterConfiguration, kubeletDir, patchesDir, out); err != nil {
172			return errors.Wrap(err, "error writing kubelet configuration to file")
173		}
174	
175		if dryRun { // Print what contents would be written
176			err := dryrunutil.PrintDryRunFile(kubeadmconstants.KubeletConfigurationFileName, kubeletDir, kubeadmconstants.KubeletRunDirectory, out)
177			if err != nil {
178				return errors.Wrap(err, "error printing kubelet configuration file on dryrun")
179			}
180		}
181		return nil
182	}
