45	// WriteConfigToDisk writes the kubelet config object down to a file
46	// Used at "kubeadm init" and "kubeadm upgrade" time
47	func WriteConfigToDisk(cfg *kubeadmapi.ClusterConfiguration, kubeletDir, patchesDir string, output io.Writer) error {
48		kubeletCfg, ok := cfg.ComponentConfigs[componentconfigs.KubeletGroup]
49		if !ok {
50			return errors.New("no kubelet component config found")
51		}
52	
53		if err := kubeletCfg.Mutate(); err != nil {
54			return err
55		}
56	
57		kubeletBytes, err := kubeletCfg.Marshal()
58		if err != nil {
59			return err
60		}
61	
62		// Apply patches to the KubeletConfiguration
63		if len(patchesDir) != 0 {
64			kubeletBytes, err = applyKubeletConfigPatchesFunc(kubeletBytes, patchesDir, output)
65			if err != nil {
66				return errors.Wrap(err, "could not apply patches to the KubeletConfiguration")
67			}
68		}
69	
70		if features.Enabled(cfg.FeatureGates, features.NodeLocalCRISocket) {
71			file := filepath.Join(kubeletDir, kubeadmconstants.KubeletInstanceConfigurationFileName)
72			kubeletBytes, err = applyKubeletConfigPatchFromFile(kubeletBytes, file, output)
73			if err != nil {
74				return errors.Wrapf(err, "could not apply kubelet instance configuration as a patch from %q", file)
75			}
76		}
77		return writeConfigBytesToDisk(kubeletBytes, kubeletDir, kubeadmconstants.KubeletConfigurationFileName)
78	}
